import os
import json
import requests

def upsert_document(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("FIREBASE_WEB_API_KEY")
    project_id = config.get("project_id") or os.getenv("FIREBASE_PROJECT_ID")
    collection = config.get("collection") or "documents"
    document_id = payload.get("id") or payload.get("primary_id")

    if not api_key:
        raise ValueError("Missing Firebase API key")
    if not project_id:
        raise ValueError("Missing Firebase project ID")
    if not document_id:
        raise ValueError("Missing primary identifier in payload")

    document = {k: v for k, v in payload.items() if k not in ("id", "primary_id")}
    url = (
        f"https://firestore.googleapis.com/v1/projects/{project_id}/databases/(default)"
        f"/documents/{collection}/{document_id}?key={api_key}"
    )
    body = {"fields": _to_firestore_fields(document)}
    result = requests.patch(url, json=body, timeout=config.get("timeout", 30))
    result.raise_for_status()
    return result.json()

def _to_firestore_fields(value):
    if value is None:
        return {"nullValue": None}
    if isinstance(value, bool):
        return {"booleanValue": value}
    if isinstance(value, int) and not isinstance(value, bool):
        return {"integerValue": str(value)}
    if isinstance(value, float):
        return {"doubleValue": value}
    if isinstance(value, str):
        return {"stringValue": value}
    if isinstance(value, dict):
        return {"mapValue": {"fields": {k: _to_firestore_fields(v) for k, v in value.items()}}}
    if isinstance(value, list):
        return {"arrayValue": {"values": [_to_firestore_fields(v) for v in value]}}
    return {"stringValue": json.dumps(value)}
